"""Fresh five-source Lake build and unchanged official checker replay."""
from pathlib import Path
import argparse,hashlib,json,os,shutil,subprocess,time
arg=argparse.ArgumentParser();arg.add_argument('--lean',type=Path,required=True);arg.add_argument('--out',type=Path,required=True);a=arg.parse_args()
root=Path(__file__).resolve().parent;out=a.out.resolve();out.mkdir(exist_ok=False)
sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest()
assert sha(a.lean)=='ec7a472d1c12a09b0c0c718f7427c2be527b3f5f07810fdbe076c2507c7a91ea'
assert sha(root/'Check.lean')=='b882f2527a1d6e720828a0c729cc80c3977905ed9207d09af22f8d153a073905'
meta=json.loads((root/'INPUTS.json').read_text())
for f in meta['files']:assert sha(root/f['path'])==f['sha256']
project=out/'project';project.mkdir();shutil.copytree(root/'sources',project/'lean')
shutil.copyfile(root/'Check.lean',project/'Check.lean')
(project/'lean/lakefile.toml').write_text('name = "clockdrop"\nversion = "0.1.0"\n[[lean_lib]]\nname = "Ruliology"\n')
env=dict(os.environ,PATH=str(a.lean.parent)+os.pathsep+os.environ.get('PATH',''),LEAN_NUM_THREADS='1');env.pop('LEAN_PATH',None);env.pop('LEAN_SRC_PATH',None)
def run(args,name):
    with (out/name).open('wb') as log:r=subprocess.run(args,cwd=project/'lean',env=env,stdout=log,stderr=subprocess.STDOUT)
    if r.returncode:print((out/name).read_text(encoding='utf-8',errors='replace')[-7000:]);r.check_returncode()
start=time.monotonic();module='Ruliology.CellularAutomata.Rule30PeriodTwoContact';lake=a.lean.parent/'lake.exe'

for idx,dependency in enumerate(meta['build_order']):run([str(lake),'build',dependency],f'build-{idx:02d}.log')
(out/'build.log').write_bytes(b''.join((out/f'build-{i:02d}.log').read_bytes() for i in range(len(meta['build_order']))))
specs={'Ruliology.CellularAutomata.Rule30RightPrefixClock': ['Ruliology.CellularAutomata.Rule30RightPrefixClock.growth_antiperiod', 'Ruliology.CellularAutomata.Rule30RightPrefixClock.exponent_step', 'Ruliology.CellularAutomata.Rule30RightPrefixClock.no_11011', 'Ruliology.CellularAutomata.Rule30RightPrefixClock.exists_prefix_exponent', 'Ruliology.CellularAutomata.Rule30RightPrefixClock.actual_no_11011', 'Ruliology.CellularAutomata.Rule30RightPrefixClock.actual_recurrence'], 'Ruliology.CellularAutomata.Rule30RightPrefixBound': ['Ruliology.CellularAutomata.Rule30RightPrefixBound.exponent_two_mul_le', 'Ruliology.CellularAutomata.Rule30RightPrefixBound.exponent_le_B', 'Ruliology.CellularAutomata.Rule30RightPrefixBound.prefixExponent_spec', 'Ruliology.CellularAutomata.Rule30RightPrefixBound.right_bounded_exponent_half', 'Ruliology.CellularAutomata.Rule30RightPrefixBound.right_bounded_prefix_half', 'Ruliology.CellularAutomata.Rule30RightPrefixBound.evol_right_diagonal_half'], 'Ruliology.CellularAutomata.Rule30FrontHalfPeriod': ['Ruliology.CellularAutomata.Rule30FrontHalfPeriod.code_high', 'Ruliology.CellularAutomata.Rule30FrontHalfPeriod.anchors', 'Ruliology.CellularAutomata.Rule30FrontHalfPeriod.orb_bit', 'Ruliology.CellularAutomata.Rule30FrontHalfPeriod.front_half_period_zero', 'Ruliology.CellularAutomata.Rule30FrontHalfPeriod.front_half_period'], 'Ruliology.CellularAutomata.Rule30PrefixClockGrowth': ['Ruliology.CellularAutomata.Rule30PrefixClockGrowth.edge_witness', 'Ruliology.CellularAutomata.Rule30PrefixClockGrowth.prefix_period_edge_bound', 'Ruliology.CellularAutomata.Rule30PrefixClockGrowth.prefix_exponent_lower', 'Ruliology.CellularAutomata.Rule30PrefixClockGrowth.prefix_exponents_unbounded', 'Ruliology.CellularAutomata.Rule30PrefixClockGrowth.two_sided_prefix_clock'], 'Ruliology.CellularAutomata.Rule30ProfileGraph': ['Ruliology.CellularAutomata.Rule30ProfileGraph.wordPer_iff', 'Ruliology.CellularAutomata.Rule30ProfileGraph.wordStep_sound', 'Ruliology.CellularAutomata.Rule30ProfileGraph.next_sound', 'Ruliology.CellularAutomata.Rule30ProfileGraph.reachable_pair', 'Ruliology.CellularAutomata.Rule30ProfileGraph.reachable_period_inherits', 'Ruliology.CellularAutomata.Rule30ProfileGraph.actual_period_inherits', 'Ruliology.CellularAutomata.Rule30ProfileGraph.actual_prefix_from_last', 'Ruliology.CellularAutomata.Rule30ProfileGraph.actual_last_minimal', 'Ruliology.CellularAutomata.Rule30ProfileGraph.actual_no_small_clock_drop'], 'Ruliology.CellularAutomata.Rule30Certificates.ProfileGraph32': ['Ruliology.CellularAutomata.Rule30ProfileGraphCases.all_nodes_checked', 'Ruliology.CellularAutomata.Rule30ProfileGraphCases.graph_valid', 'Ruliology.CellularAutomata.Rule30ProfileGraphCases.root_a', 'Ruliology.CellularAutomata.Rule30ProfileGraphCases.root_b'], 'Ruliology.CellularAutomata.Rule30ProfileGraphCases': ['Ruliology.CellularAutomata.Rule30ProfileGraphCases.actual_small_clock_minimal', 'Ruliology.CellularAutomata.Rule30ProfileGraphCases.actual_no_drop_below_sixty_four'], 'Ruliology.CellularAutomata.Rule30Certificates.ProfileClockRank32': ['Ruliology.CellularAutomata.Rule30ProfileClockEscape.next_chosen', 'Ruliology.CellularAutomata.Rule30ProfileClockEscape.extension_rank_bound', 'Ruliology.CellularAutomata.Rule30ProfileClockEscape.actual_escape', 'Ruliology.CellularAutomata.Rule30ProfileClockEscape.rank_valid'], 'Ruliology.CellularAutomata.Rule30ProfileClockEscape': ['Ruliology.CellularAutomata.Rule30ProfileClockEscape.no_period32_extension', 'Ruliology.CellularAutomata.Rule30ProfileClockEscape.nonperiod_two_forces_clock64', 'Ruliology.CellularAutomata.Rule30ProfileClockEscape.small_clock_escape', 'Ruliology.CellularAutomata.Rule30ProfileClockEscape.global_period32_forces_period2'], 'Ruliology.CellularAutomata.Rule30ProfileClockSharpness': ['Ruliology.CellularAutomata.Rule30ProfileClockSharpness.finite_profiles_unique', 'Ruliology.CellularAutomata.Rule30ProfileClockSharpness.realize_words', 'Ruliology.CellularAutomata.Rule30ProfileClockSharpness.witness_realization', 'Ruliology.CellularAutomata.Rule30ProfileClockSharpness.witness_prefix32', 'Ruliology.CellularAutomata.Rule30ProfileClockSharpness.witness_nonperiod_two', 'Ruliology.CellularAutomata.Rule30ProfileClockSharpness.witness_clock_two', 'Ruliology.CellularAutomata.Rule30ProfileClockSharpness.witness_finite', 'Ruliology.CellularAutomata.Rule30ProfileClockSharpness.sharpness_witness', 'Ruliology.CellularAutomata.Rule30ProfileClockSharpness.thirteen_is_not_uniform'], 'Ruliology.CellularAutomata.Rule30LowClockWaves': ['Ruliology.CellularAutomata.Rule30LowClockWaves.two_alternating_force_opposite', 'Ruliology.CellularAutomata.Rule30LowClockWaves.opposite_forces_alternating', 'Ruliology.CellularAutomata.Rule30LowClockWaves.array_opposite', 'Ruliology.CellularAutomata.Rule30LowClockWaves.array_period_two', 'Ruliology.CellularAutomata.Rule30LowClockWaves.boundary_black', 'Ruliology.CellularAutomata.Rule30LowClockWaves.global32_tail_alternates', 'Ruliology.CellularAutomata.Rule30LowClockWaves.alternating_tail_period_two', 'Ruliology.CellularAutomata.Rule30LowClockWaves.alternating_tail_prefix_two', 'Ruliology.CellularAutomata.Rule30LowClockWaves.global32_iff_alternating_tail'], 'Ruliology.CellularAutomata.Rule30PeriodTwoContact': ['Ruliology.CellularAutomata.Rule30PeriodTwoContact.forcing_constant', 'Ruliology.CellularAutomata.Rule30PeriodTwoContact.contact_forces_zero', 'Ruliology.CellularAutomata.Rule30PeriodTwoContact.cover_forces_period_two', 'Ruliology.CellularAutomata.Rule30PeriodTwoContact.antiperiod_no00_toggle', 'Ruliology.CellularAutomata.Rule30PeriodTwoContact.antiperiod_no00_period_two', 'Ruliology.CellularAutomata.Rule30PeriodTwoContact.no00_nonperiod_two_no_growth', 'Ruliology.CellularAutomata.Rule30PeriodTwoContact.actual_no00_nonperiod_two_no_growth', 'Ruliology.CellularAutomata.Rule30PeriodTwoContact.period_two_successor_forces_cover', 'Ruliology.CellularAutomata.Rule30PeriodTwoContact.cover_running_forces_no00', 'Ruliology.CellularAutomata.Rule30PeriodTwoContact.contact_iff_no_return', 'Ruliology.CellularAutomata.Rule30PeriodTwoContact.counter_predecessor_no00', 'Ruliology.CellularAutomata.Rule30PeriodTwoContact.actual_step', 'Ruliology.CellularAutomata.Rule30PeriodTwoContact.actual_contact_iff_no_return', 'Ruliology.CellularAutomata.Rule30PeriodTwoContact.actual_counter_predecessor_no00']}
checks={};allheads=[]
for index,(name,short) in enumerate(specs.items()):
    heads=short;allheads+=heads
    cmd=[str(lake),'env',str(a.lean),'--run',str(project/'Check.lean'),name,'--claim','partial']
    for h in heads:cmd+=['--headline',h]
    log=f'check-{index}.log';run(cmd,log)
    c=json.loads(next(s for s in reversed((out/log).read_text(encoding='utf-8').splitlines()) if s.startswith('{')))
    assert c['verdict']=='pass' and c['replay']['ok'] and not c['newAxioms'] and all(h['ok'] and h['typeMatches'] for h in c['headlines'])
    checks[name]=c
types=out/'Types.lean';types.write_text('import Ruliology.CellularAutomata.Rule30RightPrefixClock\nimport Ruliology.CellularAutomata.Rule30RightPrefixBound\nimport Ruliology.CellularAutomata.Rule30FrontHalfPeriod\nimport Ruliology.CellularAutomata.Rule30PrefixClockGrowth\nimport Ruliology.CellularAutomata.Rule30ProfileGraph\nimport Ruliology.CellularAutomata.Rule30ProfileGraphCases\nimport Ruliology.CellularAutomata.Rule30ProfileClockEscape\nimport Ruliology.CellularAutomata.Rule30ProfileClockSharpness\nimport Ruliology.CellularAutomata.Rule30LowClockWaves\nimport Ruliology.CellularAutomata.Rule30PeriodTwoContact\n'+''.join('#check @'+h+'\n#print axioms '+h+'\n' for h in allheads),encoding='utf-8')
run([str(lake),'env',str(a.lean),str(types)],'Types.log')
for f in meta['files']:assert sha(root/f['path'])==f['sha256']
assert b'warning:' not in (out/'build.log').read_bytes()
assert sum(c['replay']['constants'] for c in checks.values())==1126 and len(allheads)==77
r={'passed':True,'official_pin':meta['pin'],'fresh_source_modules':34,'reused_objects':False,'whole_catalog_build':False,'checkers':checks,'owned_declarations':sum(c['replay']['constants'] for c in checks.values()),'headlines':len(allheads),'source_files':meta['files'],'source_warnings':b'warning:' in (out/'build.log').read_bytes(),'seconds':time.monotonic()-start}
(out/'RESULT.json').write_text(json.dumps(r,indent=2)+'\n')
print(json.dumps({'passed':True,'constants':r['owned_declarations'],'headlines':r['headlines'],'source_warnings':r['source_warnings'],'seconds':r['seconds']}))
